// Segment 4: Downstream HTTP (with hidden retries!)
long httpStart = System.nanoTime();
String response = httpClient.send(request);  // includes 2 retries × 300ms!
long httpTime = (System.nanoTime() - httpStart) / 1_000_000;  // 900ms! (3 × 300ms)
log.info("HTTP time: {}ms (retries hidden!)", httpTime);

// TOTAL: 800 + 500 + 200 + 900 = 2400ms
// Without segmenting: "2500ms latency" — can't optimize!
// With segmenting: queue wait (800ms) is the BIGGEST contributor → fix pool size!

