package com.bank.latency;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class LatencyDebugTest {

    // ═══ Segmented timing reveals hidden waits ═══
    @Test
    void segmentedTiming_revealsHiddenWaits() throws InterruptedException {
        // Simulate: queue wait + connection wait + query + HTTP
        long totalStart = System.currentTimeMillis();

        // Segment 1: Queue wait (simulated)
        long queueStart = System.currentTimeMillis();
        Thread.sleep(200);  // simulates waiting in thread pool queue
        long queueWait = System.currentTimeMillis() - queueStart;

        // Segment 2: Connection wait (simulated)
        long connStart = System.currentTimeMillis();
        Thread.sleep(150);  // simulates waiting for DB connection
        long connWait = System.currentTimeMillis() - connStart;

        // Segment 3: DB query
        long queryStart = System.currentTimeMillis();
        Thread.sleep(100);  // actual query
        long queryTime = System.currentTimeMillis() - queryStart;

        // Segment 4: HTTP with retries
        long httpStart = System.currentTimeMillis();
        Thread.sleep(300);  // retry 1: fail + retry 2: fail + retry 3: success
        long httpTime = System.currentTimeMillis() - httpStart;

        long total = System.currentTimeMillis() - totalStart;

        System.out.println("Queue wait:  " + queueWait + "ms");
        System.out.println("Conn wait:   " + connWait + "ms");
        System.out.println("DB query:    " + queryTime + "ms");
        System.out.println("HTTP+retries:" + httpTime + "ms");
        System.out.println("TOTAL:       " + total + "ms");

        // Without segmenting: "750ms latency" — where to optimize?
        // With segmenting: queue wait (200ms) + HTTP retries (300ms) = top 2!
    }

    // ═══ Pool queue wait measurement ═══
    @Test
    void measureQueueWait() throws InterruptedException {
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            1, 1, 0, TimeUnit.SECONDS, new LinkedBlockingQueue<>(100));

        // Fill the worker:
        pool.submit(() -> { try { Thread.sleep(500); } catch (InterruptedException e) {} });

        // Next task: will WAIT in queue!
        long submitTime = System.currentTimeMillis();
        Future<?> f = pool.submit(() -> {
            long queueWait = System.currentTimeMillis() - submitTime;
            System.out.println("Queue wait: " + queueWait + "ms");
            assertThat(queueWait).isGreaterThanOrEqualTo(400);  // waited ~500ms!
        });

        f.get(10, java.util.concurrent.TimeUnit.SECONDS);
        pool.shutdown();
    }

    // ═══ Retry multiplication ═══
    @Test
    void retries_multiplyLatency() {
        int retries = 3;
        long perCallMs = 300;
        long totalWithRetries = retries * perCallMs;

        System.out.println("Single call: " + perCallMs + "ms");
        System.out.println("With " + retries + " retries: " + totalWithRetries + "ms");
        assertThat(totalWithRetries).isEqualTo(900);
        // 300ms call × 3 retries = 900ms! Hidden 3× latency multiplication!
    }
}
